export type Copy = Record<TranslationKey, string>;

// Preferencias ficam no navegador; a landing e o anotador leem as mesmas chaves,
// para a escolha de idioma e tema valer nas duas telas.
export function storedLanguage(): Language {
  if (typeof window === "undefined") return "pt";
  const stored = localStorage.getItem("epiaka-language");
  return stored === "en" || stored === "fr" || stored === "es" ? stored : "pt";
}

export function storedTheme(): ThemeMode {
  if (typeof window === "undefined") return "system";
  const stored = localStorage.getItem("epiaka-theme");
  return stored === "light" || stored === "dark" ? stored : "system";
}

// Interpola {n}, {name}, {status}... nos textos traduzidos.
export function fill(template: string, values: Record<string, string | number>) {
  return template.replace(/\{(\w+)\}/g, (whole, key) =>
    key in values ? String(values[key]) : whole);
}

export function getCopy(language: Language) {
  return translations[language];
}
